class TestListEnvelopeShapes:
    """Empty list envelopes are valid 'found nothing' answers, not warnings."""

    def test_empty_envelopes_pass_without_warning(self, caplog):
        import logging

        for payload in ('{"nodes": []}', '{"items": []}', '{"merges": []}'):
